/// Port of `atom.Lookup` (atom.go:57): the atom whose name is `s`, case-sensitively.
pub fn lookup(s: &[u8]) -> Option<Atom> {
    BY_NAME
        .binary_search_by(|(n, _)| n.as_bytes().cmp(s))
        .ok()
        .map(|i| BY_NAME[i].1)
}
